/* lib2.js: home (scheda in evidenza + griglia), cassetto laterale, caricamento fonti, menu delle schede e del lettore */
const UPQ=[],PAL=['#FFD233','#E3F77A','#A5F77F','#7FF7A6','#7FFAE0','#7FD6FF','#B3C4FF','#C7B3FF','#EDB3FF','#FFB3E8','#FFADB8','#FFC4A3'];
const rgba=(h,a)=>{const n=parseInt(String(h).slice(1),16)||0;return`rgba(${n>>16&255},${n>>8&255},${n&255},${a})`};
const kcol=w=>w.col||S.kwc||PAL[0];
const ago=t=>{const d=Math.floor((Date.now()-t)/864e5);return d<=0?'oggi':d==1?'ieri':d+' giorni fa'};
const docMeta=d=>`${d.prog||0}% letto${d.pages?' · '+d.pages+' pag.':''}`;
const dateTxt=d=>d.id>1e12?'Aggiunta '+ago(d.id):'';
const coverHTML=d=>d.kind=='pdf'||d.cover?`<img data-t=${d.id} onerror="this.remove()">`:'';
const stopDrop=()=>window.__nodrop&&Date.now()-window.__nodrop<400;
function openDoc(id){if(stopDrop())return;if(S.pm){ACT.pick(id);save();render();return}A('open',id)}
/* ---------- schede ---------- */
function heroHTML(d){const pk=S.pick.includes(d.id);return`<article id=dc${d.id} class="hero2 card2${pk?' pk':''}" data-doc=${d.id} onclick="openDoc(${d.id})">${S.pm?`<i class="chk${pk?' on':''}"></i>`:''}<div class=hcv>${coverHTML(d)}<div class=exc>${esc((d.paras[0]||'').slice(0,300))}</div></div><div class=hbd><span class="tag hi">Più recente</span><h2>${esc(d.title)}</h2><div class="mono mut">${dateTxt(d)}${dateTxt(d)?'<br>':''}${docMeta(d)}</div><div class=tagrow>${(d.tags||[]).map(t=>`<span class=tg>${esc(t)}</span>`).join('')}<span class="tg add" onclick="event.stopPropagation();editTags(${d.id})">+ Tag</span></div></div><button class=cmb onclick="cardMenu(event,${d.id})">${I('ellipsis-vertical')}</button><div class=prog><i style="width:${d.prog||0}%"></i></div></article>`}
function cardHTML(d){const pk=S.pick.includes(d.id);return`<article id=dc${d.id} class="pc card2${pk?' pk':''}" data-doc=${d.id} onclick="openDoc(${d.id})">${S.pm?`<i class="chk${pk?' on':''}"></i>`:''}<div class=pcv>${coverHTML(d)}<div class=exc>${esc((d.paras[0]||'').slice(0,260))}</div></div><div class=pcb><h3>${esc(d.title)}</h3><div class="mono mut">${docMeta(d)}</div>${(d.tags||[]).length?`<div class=tagrow>${d.tags.slice(0,2).map(t=>`<span class=tg>${esc(t)}</span>`).join('')}</div>`:''}</div><button class=cmb onclick="cardMenu(event,${d.id})">${I('ellipsis-vertical')}</button><div class=prog><i style="width:${d.prog||0}%"></i></div></article>`}
function libDocs(){const q=S.find.toLowerCase();let D=S.docs.filter(d=>(!S.colf||d.col==S.colf)&&(!q||d.title.toLowerCase().includes(q)||(d.tags||[]).some(t=>t.toLowerCase().includes(q))));return D}
function libBody(){const sk=UPQ.filter(u=>!u.doc&&u.st!='err');if(!S.docs.length&&!sk.length)return emptyBox('library-big','La libreria è vuota','Carica una fonte con il pulsante ＋ in alto');
 const D=libDocs(),by=[...D].sort((a,b)=>(b.last||b.id)-(a.last||a.id)),hero=S.find?null:by[0];let rest=D.filter(d=>d!==hero);if(S.ord=='tit')rest.sort((a,b)=>a.title.localeCompare(b.title));else rest.sort((a,b)=>b.id-a.id);
 return`${hero?heroHTML(hero):''}${rest.length||sk.length?`<div class="grid2 ${S.lay=='list'?'one':''}">${sk.map(()=>`<div class="pc sk"><div class=pcv></div></div>`).join('')}${rest.map(cardHTML).join('')}</div>`:''}${!D.length&&!sk.length?emptyBox('folder','Nessuna fonte qui','Trascina una fonte in questa collezione'):''}`}
const libRefresh=()=>{const b=document.getElementById('libbody');if(b){morphInto(b,libBody());fillCovers()}};
function libView(){const cn=S.colf?esc((S.cols.find(c=>c.id==S.colf)||{}).name||''):'Libreria';return`<main>${typeof updBanner=='function'?updBanner():''}<div class=sec><span class=mono>${cn}</span><span class="mono mut">${libDocs().length} ${libDocs().length==1?'fonte':'fonti'}</span></div><div id=libbody>${libBody()}</div></main>`}
function libTop(v){if(S.pm&&v=='lib')return`<div class="top m"><button onclick="A('pm',0)">${I('x')}</button><b style="flex:1;text-align:center">${S.pick.length} selezionate</b><button onclick="A('pickcol')" ${S.pick.length?'':'disabled'}>${I('folder-plus')}</button><button onclick="A('picktag')" ${S.pick.length?'':'disabled'}>${I('tag')}</button><button onclick="A('pickdel')" ${S.pick.length?'':'disabled'} style="color:#ff8f8f">${I('trash-2')}</button></div>`;
 return`<div class=top><button onclick="A('menu','dots')">${I('ellipsis-vertical')}</button><div class=sp></div>${v=='lib'?`<button onclick="A('menu','plus')">${I('plus')}${I('chevron-down')}</button>`:`<button onclick="A('modal','deck')">${I('plus')}</button>`}<div class=sp></div>${v=='lib'?`<button class="${S.sq||S.find?'on':''}" onclick="S.sq=!S.sq;if(!S.sq)S.find='';render()">${I('search')}${I('chevron-down')}</button>`:'<span style="width:44px"></span>'}</div>${v=='lib'&&(S.sq||S.find)?`<div style="padding:0 14px"><input id=qs value="${esc(S.find)}" placeholder="Cerca per titolo o tag" oninput="S.find=this.value;libRefresh()"></div>`:''}`}
const libPage=v=>libTop(v)+(v=='lib'?libView():deckView())+drawerHTML();
/* ---------- cassetto laterale ---------- */
function drawerHTML(){const q=allQ(),dueN=q.filter(x=>x.due<=today()).length,newN=q.filter(x=>!x.lm&&!(x.box>1)).length,seenN=q.length-newN,nm=localStorage.getItem('studio.uname')||'Il mio profilo',ini=((nm.match(/\p{L}/gu)||['S']).slice(0,2).join('')).toUpperCase(),x=S.drx||{col:1,dk:1,set:0},row=(ic,t,f,n,on,cls)=>`<div class="di${on?' on':''}" onclick="${f}">${ic?I(ic):'<i style="width:18px"></i>'}<span>${t}</span>${n!==undefined?`<b class="${cls||''}">${n}</b>`:''}</div>`,sub=(t,f,n,cls)=>`<div class="di sb2" onclick="${f}"><i class=ph></i><span>${t}</span><b class="${cls}">${n}</b></div>`;
 return`<div class="dov${S.dr?' on':''}" onclick="A('dr',0)"></div><aside class="drw${S.dr?' on':''}"><div class=dhd onclick="A('uname')"><div class=av>${esc(ini)}</div><span>${esc(nm)}</span>${typeof GT!='undefined'&&GT.get()?'<em class=pl>Drive</em>':''}${I('chevron-down')}</div>
 ${row('library-big','Libreria',"A('nav','lib')",S.docs.length,S.view=='lib'&&!S.colf)}
 <div class="di sec2" onclick="A('drx','col')"><i class="chv ${x.col?'o':''}">${I('chevron-down')}</i>${I('folder')}<span>Collezioni</span><b>${S.cols.length}</b></div>${x.col?S.cols.map(c=>`<div class="di sb2${S.colf==c.id?' on':''}" onclick="A('colf',${c.id})"><i class=ph></i><span>${esc(c.name)}</span><b>${S.docs.filter(d=>d.col==c.id).length}</b><span class=acts onclick="event.stopPropagation()"><button onclick="A('colren',${c.id})">${I('pencil')}</button><button onclick="A('colrm',${c.id})">${I('trash-2')}</button></span></div>`).join('')+`<div class="di sb2" onclick="A('colnew')"><i class=ph></i>${I('plus')}<span>Nuova collezione</span></div>`:''}
 <div class="di sec2" onclick="A('drx','dk')"><i class="chv ${x.dk?'o':''}">${I('chevron-down')}</i>${I('layers')}<span>Mazzi flashcard</span><b>${S.decks.length}</b></div>${x.dk?sub('Tutti i mazzi',"A('nav','deck')",S.decks.length,'')+sub('Flashcard da ripassare',"A('studyf','due')",dueN,'r')+sub('Flashcard mai studiate',"A('studyf','new')",newN,'y')+sub('Flashcard già studiate',"A('studyf','seen')",seenN,'g'):''}
 <div class="di sec2" onclick="A('drx','set')"><i class="chv ${x.set?'o':''}">${I('chevron-down')}</i>${I('settings')}<span>Impostazioni</span></div>${x.set?`${sub('Sincronizzazione Drive',"A('dr',0);A('modal','sync')",'','')}${sub('Assistente AI (Gemini)',"A('dr',0);A('modal','key')",'','')}${sub('Backup',"A('dr',0);A('modal','bk')",'','')}${sub('Controlla aggiornamenti',"A('dr',0);checkUpdate(true)",'','')}${sub('Disposizione: '+(S.lay=='list'?'lista':'griglia'),"S.lay=S.lay=='list'?'grid':'list';render()",'','')}${sub('Ordina per: '+(S.ord=='tit'?'titolo':'inserimento'),"S.ord=S.ord=='tit'?'ins':'tit';render()",'','')}`:''}</aside><div class=edge onclick="A('dr',1)"></div>`}
/* ---------- azioni ---------- */
const nowM=()=>Date.now();
const ACT={
 dr:x=>{S.dr=x===undefined?!S.dr:!!x;S.menu=null},
 drx:k=>{S.drx=S.drx||{col:1,dk:1,set:0};S.drx[k]=S.drx[k]?0:1},
 nav:v=>{S.view=v;S.colf=null;S.dr=false;S.rev=null;S.pm=false},
 colf:id=>{S.view='lib';S.colf=id;S.dr=false;S.pm=false},
 uname:async()=>{const r=await form('Il tuo nome',[{l:'Nome',v:localStorage.getItem('studio.uname')||''}]);if(r)localStorage.setItem('studio.uname',r[0].trim())},
 colnew:async()=>{const r=await form('Nuova collezione',[{l:'Nome',v:''}],'Crea');if(r&&r[0].trim()){const c={id:nowM(),name:r[0].trim(),mod:nowM()};S.cols.push(c);return c}},
 colren:async id=>{const c=S.cols.find(c=>c.id==id),r=await form('Rinomina collezione',[{l:'Nome',v:c.name}]);if(r&&r[0].trim()){c.name=r[0].trim();c.mod=nowM()}},
 colrm:async id=>{if(await sure('Eliminare la collezione? Le fonti restano nella libreria.')){(S.del=S.del||[]).push({id,t:nowM()});S.cols=S.cols.filter(c=>c.id!=id);S.docs.forEach(d=>{if(d.col==id){d.col=null;d.mod=nowM()}});if(S.colf==id)S.colf=null}},
 pm:on=>{S.pm=!!on;S.pick=[];S.menu=null},
 pick:id=>{S.pick=S.pick.includes(id)?S.pick.filter(i=>i!=id):[...S.pick,id]},
 pickcol:()=>{S.addc={ids:[...S.pick]};S.modal='addcol'},
 picktag:async()=>{const r=await form('Aggiungi tag alle fonti selezionate',[{l:'Tag (separati da virgola)',v:''}]);if(r){const t=r[0].split(',').map(x=>x.trim()).filter(Boolean);S.docs.forEach(d=>{if(S.pick.includes(d.id)){d.tags=[...new Set([...(d.tags||[]),...t])];d.mod=nowM()}})}},
 pickdel:async()=>{if(await sure(`Eliminare ${S.pick.length} fonti con note, domande e mappe?`)){S.pick.forEach(id=>(S.del=S.del||[]).push({id,t:nowM()}));S.docs=S.docs.filter(d=>!S.pick.includes(d.id));S.pm=false;S.pick=[]}},
 studyf:k=>{const Q=allQ().filter(q=>k=='due'?q.due<=today():k=='new'?(!q.lm&&!(q.box>1)):(q.lm||q.box>1));S.dr=false;S.view='deck';S.pm=false;if(Q.length)S.rev={id:null,m:k=='due'?'due':'all',q:Q.map(c=>c.id),k:0,show:false}},
 fit:f=>{S.fit=f;PV.zoom=1;PV.scale=0;S.menu=null;fitPages()},
 showsel:()=>{S.showsel=S.showsel===false},
 imm:()=>{S.imm=!S.imm;S.menu=null;document.body.classList.toggle('imm',S.imm)},
 pgtheme:t=>{S.pgt=t;S.menu=null},
 tsz:dx=>{S.tsz=Math.max(.8,Math.min(1.8,(S.tsz||1)+dx))},
 kwc:c=>{S.kwc=c},
 kwcust:c=>{S.kwcust=[...(S.kwcust||[]).filter(x=>x!=c),c].slice(-6);S.kwc=c}
};
function A2(n,x){const f=ACT[n];return f?Promise.resolve(f(x)):undefined}
function setZoomPct(p){const b=fitBase();PV.zoom=Math.max(.3,Math.min(5,p/100/b));PV.scale=0;S.menu=null;fitPages();render()}
function fitBase(){const m=Math.max(...PM.pages.map(p=>p.w)),M=Math.max(...PM.pages.map(p=>p.h));return S.fit=='h'?(PV.el.clientHeight-24)/M:Math.min(1.8,(PV.el.clientWidth-24)/m)}
async function editTags(id){const d=S.docs.find(o=>o.id==id),r=await form('Modifica tag',[{l:'Tag (separati da virgola)',v:(d.tags||[]).join(', ')}]);if(r){d.tags=r[0].split(',').map(x=>x.trim()).filter(Boolean);d.mod=nowM();save();render()}}
function cardMenu(e,id){e.stopPropagation();const r=e.currentTarget.getBoundingClientRect();S.mxy=[r.bottom+6,r.right];S.menu='cd'+id;render()}
function addToCol(cid){const ids=(S.addc&&S.addc.ids)||[];S.docs.forEach(d=>{if(ids.includes(d.id)){d.col=cid;d.mod=nowM()}});S.modal=null;S.pm=false;S.pick=[];S.addc=null;save();render()}
async function newColAdd(){const c=await ACT.colnew();if(c)addToCol(c.id)}
async function dropCol(){const a=S.docs.find(d=>d.id==S.drop.a),b=S.docs.find(d=>d.id==S.drop.b);S.modal=null;let cid=b.col;if(!cid){const c=await ACT.colnew();if(!c){render();return}cid=c.id;b.col=cid;b.mod=nowM()}a.col=cid;a.mod=nowM();S.drop=null;save();render()}
async function dlDoc(id){const d=S.docs.find(o=>o.id==id);S.menu=null;render();if(d.kind=='pdf'){const b=await idbGet('f'+id);if(b)return dl(new Blob([b],{type:'application/pdf'}),(d.title||'documento')+'.pdf')}dl(new Blob([d.paras.join('\n\n')],{type:'text/plain'}),(d.title||'documento')+'.txt')}
async function setCoverImg(f){if(!f)return;const id=S.cvid,im=new Image();im.onload=async()=>{const k=Math.min(1,420/im.width),c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);await idbSet('t'+id,c.toDataURL('image/jpeg',.8));S.docs.find(o=>o.id==id).cover=true;S.modal=null;save();render()};im.src=URL.createObjectURL(f)}
async function setCoverPage(){const id=S.cvid,n=Math.max(1,+document.getElementById('cvp').value||1),buf=await idbGet('f'+id);if(!buf)return;const lib=await pj(),pdf=await lib.getDocument({data:new Uint8Array(buf.slice(0))}).promise,pg=await pdf.getPage(Math.min(n,pdf.numPages)),v=pg.getViewport({scale:.5}),c=document.createElement('canvas');c.width=v.width;c.height=v.height;await pg.render({canvasContext:c.getContext('2d'),viewport:v}).promise;await idbSet('t'+id,c.toDataURL('image/jpeg',.75));S.docs.find(o=>o.id==id).cover=true;S.modal=null;save();render()}
function toggleKw(){}
/* ---------- menu ---------- */
const row=(ic,t,f,extra,cls)=>`<div onclick="${f}" class="${cls||''}">${ic?I(ic):''}<span style="flex:1">${t}</span>${extra||''}</div>`;
function cdMenu(id){const d=S.docs.find(o=>o.id==id);if(!d)return'';const y=S.mxy[0],pos=`top:${Math.min(y,innerHeight-430)}px;left:${Math.max(8,Math.min(innerWidth-262,S.mxy[1]-254))}px;width:254px`;
 return mn(pos,`${row('square-check-big','Seleziona',`S.menu=null;A('pm',1);A('pick',${id})`)}${row('book-open','Leggi',`A('open',${id})`)}<div class=h>ORGANIZZA</div>${row('pencil','Rinomina',`S.menu=null;A('rndoc',${id})`)}${row('folder-plus','Aggiungi a collezione',`S.menu=null;S.addc={ids:[${id}]};S.modal='addcol';render()`)}${row('tag','Modifica tag',`S.menu=null;editTags(${id})`,'<span class=mut>T</span>')}<div class=h>OPZIONI FONTE</div>${row('image','Modifica copertina',`S.menu=null;S.cvid=${id};S.modal='cover';render()`)}${row('combine','Unisci fonti',`S.menu=null;tell("L'unione delle fonti arriva in una prossima versione.")`)}${row('download','Scarica',`dlDoc(${id})`)}${row('trash-2','Elimina',`S.menu=null;A('rmdoc',${id})`,'','x')}`)}
function plusLib(){return mn('top:56px;left:50%;transform:translateX(-50%)',`<div class=h>AGGIUNGI FONTE</div>${row('file-text','File (PDF, Word, PowerPoint, TXT)',"S.menu=null;A('modal','file')")}${row('file-plus','Testo (incolla)',"S.menu=null;A('modal','text')")}<div class=mut style="padding:6px 12px">Pagine web, audio e video: prossimamente</div><div class=h>ORGANIZZA</div>${row('folder-plus','Nuova collezione',"S.menu=null;A('colnew')")}${row('square-check-big','Seleziona fonti',"A('pm',1)")}`)}
function readerMenu(){const d=doc(),pdf=d.kind=='pdf'&&!S.pdfText&&PV.el&&PV.scale,pct=PV.scale?Math.round(PV.scale*100):0,chk=on=>on?I('check'):'',sw=(c,on)=>`<i class="sw2${on?' on':''}" style="background:${c}" onclick="A('kwc','${c}')"></i>`,cu=S.kwcust||[];
 return mn('top:56px;left:8px;width:min(330px,94vw);max-height:86vh;overflow:auto',`<div class=h>NAVIGAZIONE</div>${row('library-big','Cambia fonte',"S.menu='src';render()",I('chevron-right'))}<div class=h>VISUALIZZAZIONE</div>${pdf?row('zoom-in','Zoom',"S.menu='zoom';render()",`<span class=mut>${pct}%</span>`+I('chevron-right'))+row('fullscreen','Schermo intero',"A('imm')")+row('move-horizontal','Adatta alla larghezza',"A('fit','w')",chk(S.fit!='h'))+row('move-vertical',"Adatta all'altezza","A('fit','h')",chk(S.fit=='h')):row('fullscreen','Schermo intero',"A('imm')")}${row('image','Visualizza selezioni',"A('showsel')",chk(S.showsel!==false))}<div class=h>STRUMENTI</div>${row('search','Cerca nel testo',"S.menu=null;A('modal','find')")}${row('panel-left','Indice',"A('side','idx')")}${d.kind=='pdf'?row('layers','Anteprime pagine',"A('side','th')")+row('align-left',S.pdfText?'Mostra le pagine':'Mostra il testo estratto',"A('pt')"):''}${row('file-text','Esporta appunti (.md)',"exportMd()")}<div class=h>OPZIONI FONTE</div>${row('pencil','Rinomina',`S.menu=null;A('rndoc',${d.id})`)}${row('combine','Unisci fonti',"S.menu=null;tell(\"L'unione delle fonti arriva in una prossima versione.\")")}${row('settings','Personalizza',"S.menu='pers';render()",I('chevron-right'))}${row('trash-2','Elimina',`S.menu=null;readDel(${d.id})`,'','x')}<div class=h>COLORE PAROLE CHIAVE</div><div class=swg>${PAL.map(c=>sw(c,(S.kwc||PAL[0])==c)).join('')}</div><div class=h style="display:flex;justify-content:space-between"><span>I TUOI COLORI</span><span>${cu.length}/6</span></div><div class=swg>${cu.map(c=>sw(c,S.kwc==c)).join('')}${cu.length<6?`<i class="sw2 add" onclick="document.getElementById('kwpick').click()">${I('plus')}</i>`:''}</div><input type=color id=kwpick value="#ffd233" style="position:absolute;opacity:0;pointer-events:none;width:0;height:0" onchange="A('kwcust',this.value)">`)}
async function readDel(id){if(await sure('Eliminare questo documento con note, domande e mappe?')){(S.del=S.del||[]).push({id,t:nowM()});S.docs=S.docs.filter(o=>o.id!=id);S.view='lib';save();render()}}
function menus2(m){if(typeof m!='string')return'';
 if(m.startsWith('cd'))return cdMenu(+m.slice(2));
 if(m=='plus'&&S.view=='lib')return plusLib();
 if(m=='dots'&&S.view=='read')return readerMenu();
 if(m=='src')return mn('top:56px;left:8px;width:min(330px,94vw);max-height:80vh;overflow:auto',`<div class=h>CAMBIA FONTE</div>${S.docs.map(o=>row('book-open',esc(o.title),`S.menu=null;A('open',${o.id})`,o.id==S.cur?I('check'):'')).join('')}`);
 if(m=='zoom')return mn('top:56px;left:8px;width:min(330px,94vw)',`<div class=h>ZOOM · ${Math.round((PV.scale||1)*100)}%</div>${[50,75,100,125,150,200,300].map(p=>row('zoom-in',p+'%',`setZoomPct(${p})`)).join('')}`);
 if(m=='pers')return mn('top:56px;left:8px;width:min(330px,94vw)',`<div class=h>TEMA DELLE PAGINE PDF</div>${[['n','Normale'],['d','Scuro'],['s','Seppia']].map(([k,t])=>row('image',t,`A('pgtheme','${k}')`,(S.pgt||'n')==k?I('check'):'')).join('')}<div class=h>TESTO ESTRATTO</div>${row('plus','Testo più grande',"A('tsz',.1)")}${row('minus','Testo più piccolo',"A('tsz',-.1)")}`);
 return''}
function modalLib(){if(S.modal=='addcol')return`<div class=ov onclick="A('close')"></div><div class=modal><h2>Aggiungi a collezione</h2>${S.cols.map(c=>`<div class=item style="cursor:pointer;display:flex;gap:8px;align-items:center" onclick="addToCol(${c.id})">${I('folder')}<span style="flex:1">${esc(c.name)}</span><span class="mono mut">${S.docs.filter(d=>d.col==c.id).length}</span></div>`).join('')||'<div class=mut>Nessuna collezione.</div>'}<button style="width:100%;margin-top:8px" onclick="newColAdd()">${I('plus')}Nuova collezione</button></div>`;
 if(S.modal=='drop'&&S.drop){const a=S.docs.find(d=>d.id==S.drop.a),b=S.docs.find(d=>d.id==S.drop.b);if(!a||!b)return'';return`<div class=ov onclick="A('close')"></div><div class=modal><h2>Collezione o unione?</h2><div class="mono mut" style="margin-bottom:12px">«${esc(a.title)}» su «${esc(b.title)}»</div><div style="display:flex;flex-direction:column;gap:8px"><button class=pri onclick="dropCol()">${I('folder-plus')}${b.col?'Aggiungi alla collezione di «'+esc(b.title)+'»':'Crea una collezione con le due fonti'}</button><button onclick="tell('L\\'unione delle fonti arriva in una prossima versione.')">${I('combine')}Unisci in una sola fonte</button><button onclick="A('close')">Annulla</button></div></div>`}
 if(S.modal=='cover'){const d=S.docs.find(o=>o.id==S.cvid);if(!d)return'';return`<div class=ov onclick="A('close')"></div><div class=modal><h2>Modifica copertina</h2><label class=card style="display:block;text-align:center;cursor:pointer;margin-bottom:12px">${I('image')} Scegli un'immagine<input type=file accept="image/*" hidden onchange="setCoverImg(this.files[0])"></label>${d.kind=='pdf'?`<div class=lab>Oppure usa una pagina del PDF</div><div style="display:flex;gap:8px"><input id=cvp type=number min=1 max=${d.pages||1} value=1 style="margin:0"><button class=pri onclick="setCoverPage()">Usa</button></div>`:''}<p><button onclick="A('close')">Annulla</button></p></div>`}
 return''}
/* ---------- caricamento fonti ---------- */
const extOf=n=>((n.match(/\.(\w+)$/)||[])[1]||'').toLowerCase();
function upHTML(){if(!UPQ.length)return'<div id=upsheet></div>';const n=UPQ.filter(u=>u.st!='done'&&u.st!='err').length,col=S.upc;
 return`<div id=upsheet><section class=ups><div class=uph onclick="S.upc=!S.upc;upRender()"><b>${n?`Caricamento di ${n} ${n==1?'fonte':'fonti'}`:'Caricamento completato'}</b>${I('chevron-down')}</div>${col?'':UPQ.map(u=>`<div class=upr><div class="upi ${u.ext}">${(u.ext||'doc').toUpperCase().slice(0,4)}</div><div class=upm><div class=upn>${esc(u.name)}</div><div class="ups2 ${u.st=='err'?'er':''}">${esc(u.msg||'')}</div><div class=upb><div class=t1><i style="width:${Math.round(u.pct||0)}%"></i></div><div class=t2><i style="width:${Math.round(u.pct2||0)}%"></i></div></div></div>${u.doc?`<button onclick="UPQ.length=0;A('open',${u.doc})">Apri</button>`:''}<button class=xx onclick="upDismiss(${u.id})">${I('x')}</button></div>`).join('')}</section></div>`}
function upRender(){const el=document.getElementById('upsheet');if(el)morphInto(el,upHTML(),true)}
function upDismiss(id){const i=UPQ.findIndex(u=>u.id==id);if(i>=0)UPQ.splice(i,1);upRender();if(S.view=='lib')libRefresh()}
let UPRUN=false;
async function importFiles(files){S.modal=null;const list=[...files];for(const f of list)UPQ.push({id:Date.now()+Math.random(),name:f.name.replace(/\.\w+$/,''),ext:extOf(f.name),st:'wait',pct:0,msg:'In attesa…',f});render();if(UPRUN)return;UPRUN=true;
 while(true){const it=UPQ.find(u=>u.st=='wait');if(!it)break;await importOne(it)}UPRUN=false;setTimeout(()=>{if(!UPQ.some(u=>u.st!='done'&&u.st!='err')){UPQ.length=0;upRender()}},6000)}
async function importOne(it){const f=it.f;delete it.f;it.st='read';const up=(p,m)=>{it.pct=p;if(m)it.msg=m;upRender()};
 try{const ex=it.ext;let r;up(3,'Lettura…');
  if(ex=='pdf'){const buf=await f.arrayBuffer();r=await readPdf(buf,f.name,p=>up(5+p*55,'Lettura del PDF…'));if(!r.paras.length){r.paras=await ocrPdf(r.buf,(n,N)=>up(60+n/N*30,`Riconoscimento del testo: pagina ${n} di ${N}…`));delete r.model}}
  else if(ex=='docx'){await loadJs('vendor/mammoth.browser.min.js');r={title:it.name,authors:[],year:'',pages:0,paras:(await mammoth.extractRawText({arrayBuffer:await f.arrayBuffer()})).value.split(/\n+/).map(s=>s.trim()).filter(Boolean)}}
  else if(ex=='pptx')r={title:it.name,authors:[],year:'',pages:0,paras:(await readPptx(await f.arrayBuffer())).map(s=>s.trim()).filter(Boolean)};
  else r={title:it.name,authors:[],year:'',pages:0,paras:(await f.text()).split(/\n+/).map(s=>s.trim()).filter(Boolean)};
  if(!r.paras.length)throw new Error('Nessun testo trovato.');
  const id=Date.now(),d={id,title:r.title,authors:r.authors,year:r.year,pages:r.pages,paras:r.paras,kw:[],q:[],n:[],s:[],tags:[],mod:Date.now(),last:Date.now()};
  if(r.model){await idbSet('f'+id,r.buf);await idbSet('m'+id,r.model);d.kind='pdf';if(r.thumb)await idbSet('t'+id,r.thumb);if(r.idx&&r.idx.length)d.idx=r.idx.map((x,k)=>({id:id+k,lv:x.lv,t:x.t,pg:x.pg,s:x.s,i:Math.max(0,r.model.sents.findIndex(q=>q[0]==x.pg&&q[2]>x.s))}))}
  if(S.colf)d.col=S.colf;S.docs.push(d);it.doc=id;it.st='ready';up(70,'Si può già leggere');save();if(S.view=='lib')libRefresh();
  if(K()&&(ex=='pdf'||ex=='docx')){it.st='meta';it.pct2=15;up(75,'Riconoscimento di titolo e autori…');await aiMeta(r);d.title=r.title||d.title;if(r.authors.length)d.authors=r.authors;if(r.year)d.year=r.year;it.pct2=100;save();if(S.view=='lib')libRefresh()}
  it.st='done';up(100,'Completato')}catch(e){it.st='err';it.msg='Errore: '+e.message;upRender()}}
let DRG=null;
function dragStart(e){DRG.on=true;const el=DRG.el,r=el.getBoundingClientRect(),g=el.cloneNode(true);g.removeAttribute('id');g.className+=' ghost';g.style.cssText=`position:fixed;left:${r.left}px;top:${r.top}px;width:${r.width}px;height:${r.height}px;z-index:50;pointer-events:none;transform:rotate(4deg) scale(.9);opacity:.92;box-shadow:0 14px 40px #000a`;document.body.append(g);DRG.g=g;DRG.ox=e.clientX-r.left;DRG.oy=e.clientY-r.top;el.style.opacity='.35'}
const dragClear=()=>{document.querySelectorAll('.dt').forEach(x=>x.classList.remove('dt'));const p=document.getElementById('dpill');if(p)p.remove()};
document.addEventListener('pointerdown',e=>{if(S.view!='lib'||S.pm)return;const el=e.target.closest&&e.target.closest('[data-doc]');if(!el||el.classList.contains('ghost')||e.target.closest('button,.tg'))return;DRG={el,id:+el.dataset.doc,x:e.clientX,y:e.clientY,on:false,pt:e.pointerType};if(e.pointerType!=='mouse')DRG.h=setTimeout(()=>{if(DRG)dragStart(e)},380)});
addEventListener('pointermove',e=>{if(!DRG)return;if(!DRG.on){const mv=Math.hypot(e.clientX-DRG.x,e.clientY-DRG.y);if(DRG.pt==='mouse'){if(mv>6)dragStart(e)}else if(mv>8){clearTimeout(DRG.h);DRG=null}return}
 DRG.g.style.left=(e.clientX-DRG.ox)+'px';DRG.g.style.top=(e.clientY-DRG.oy)+'px';dragClear();const t=document.elementFromPoint(e.clientX,e.clientY),c=t&&t.closest&&t.closest('[data-doc]');if(c&&c!==DRG.el&&!c.classList.contains('ghost')){c.classList.add('dt');const p=document.createElement('div');p.id='dpill';p.className='dpill';p.innerHTML=I('plus')+'Collezione o unione?';c.append(p)}});
addEventListener('pointerup',e=>{if(!DRG)return;clearTimeout(DRG.h);const d=DRG;DRG=null;if(!d.on)return;const t=document.elementFromPoint(e.clientX,e.clientY),c=t&&t.closest&&t.closest('[data-doc]');dragClear();d.g.remove();d.el.style.opacity='';window.__nodrop=Date.now();if(c&&+c.dataset.doc!==d.id){S.drop={a:d.id,b:+c.dataset.doc};S.modal='drop';render()}});
addEventListener('pointercancel',()=>{if(DRG){clearTimeout(DRG.h);if(DRG.g)DRG.g.remove();dragClear();DRG=null}});
const bindLib=()=>{};
document.addEventListener('touchmove',e=>{if(document.querySelector('.ghost'))e.preventDefault()},{passive:false});
addEventListener('dragover',e=>e.preventDefault());addEventListener('drop',e=>{if(e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files.length){e.preventDefault();importFiles(e.dataTransfer.files)}});
/* scorrimento dal bordo sinistro per aprire il cassetto */
let SW=null;document.addEventListener('touchstart',e=>{const t=e.touches[0];if((S.view=='lib'||S.view=='deck')&&!S.dr&&t.clientX<56)SW={x:t.clientX,y:t.clientY,open:1};else if(S.dr)SW={x:t.clientX,y:t.clientY,open:0}},{passive:true});
document.addEventListener('touchmove',e=>{if(!SW)return;const t=e.touches[0],dx=t.clientX-SW.x,dy=Math.abs(t.clientY-SW.y);if(SW.open&&dx>40&&dy<60){SW=null;A('dr',1)}else if(!SW.open&&dx<-50&&dy<60){SW=null;A('dr',0)}},{passive:true});
document.addEventListener('touchend',()=>{SW=null},{passive:true});
